```
static void uart_stm32_poll_out(const struct device *dev, unsigned char c)
{
	USART_TypeDef *UartInstance = UART_STRUCT(dev);
	int key;

	while (1) {
		key = irq_lock();//prevent race condition if nested interrupts  or thread switch 
		if(LL_USART_IsActiveFlag_TXE(UartInstance)){

			LL_USART_ClearFlag_TC(UartInstance);
			LL_USART_TransmitData8(UartInstance, (uint8_t)c);

			irq_unlock(key);
			break;
		}
		irq_unlock(key);
		if (!k_is_in_isr() && key == 0){
			//k_msleep(1);//we in not interrupt context //but got output latency, so disable it
			k_yield();//yield execution to another thread of the same or higher priority. Its better for software, but not output pretty (some symbols  from shell some from kprint)
		}
	}
}
```

